package com.example.starter.evidence.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 交接发起请求。仅当前保管人可发起，接收人必须与发起人不同。
 *
 * @param commandKey  幂等命令键
 * @param toCustodian 指定接收人
 */
public record TransferInitiateRequest(
        @NotBlank @Size(max = 64) String commandKey,
        @NotBlank @Size(max = 64) String toCustodian) {
}

package com.example.starter.evidence.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 证物入库请求。保管人取自 X-Actor-Id，初始状态 SEALED。
 *
 * @param commandKey  幂等命令键
 * @param evidenceKey 证物业务键，全局唯一
 * @param caseKey     所属案件键
 * @param category    证物类别
 * @param sealNo      封条编号
 */
public record IntakeRequest(
        @NotBlank @Size(max = 64) String commandKey,
        @NotBlank @Size(max = 64) String evidenceKey,
        @NotBlank @Size(max = 64) String caseKey,
        @NotBlank @Size(max = 64) String category,
        @NotBlank @Size(max = 64) String sealNo) {
}

package com.example.starter.evidence;

/**
 * 命令执行结果：HTTP 状态码 + 响应体 JSON 字符串。
 * 首次执行与幂等重放均通过该形式返回，保证重放响应与首次完全一致。
 *
 * @param status HTTP 状态码
 * @param body   响应体 JSON
 */
public record StoredResponse(int status, String body) {
}

